+import org.springframework.dao.DataAccessException;
+
+import java.util.stream.Stream;
+
+/** UC-002: Browse veterinarians and their specialties with lazy loading. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians | PetClinic")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+    private final Grid<Vet> grid = new Grid<>();
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties()))
+                .setHeader("Specialties");
+        grid.setSizeFull();
+        grid.setItems(this::fetch, query -> count());
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count() {
+        try {
+            return repository.count();
+        } catch (DataAccessException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(DataAccessException exception) {
+        grid.setVisible(false);
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                ui.getInternals().getActiveViewLocation(), exception, NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
